// Write FTG's email about something a client did in the portal: a message on
// a file, a rejection with its reason, approving a file we sent, submitting
// their monthly questionnaire, or a change to their account. Camaree: "let's
// add all client actions so that we never miss anything." It only ever goes
// to FTG's own inbox, and anyone can call this webhook, so everything taken
// from the request is escaped here.
const APP = 'https://financetherapygroup.netlify.app';
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const line = (s, max) => String(s ?? '').replace(/[\r\n\t]+/g, ' ').trim().slice(0, max);

const b = $input.first().json.body || {};
const kind = String(b.kind || 'message');
const email = line(b.client_email, 200);
const who = line(b.client_name, 120) || email || 'A client';
// "did" is written here or escaped before it comes in.
const intro = did => `<p><b>${esc(who)}</b>${email && email !== who ? ' (' + esc(email) + ')' : ''} ${did}</p>`;
const file = line(b.file_name, 200) || 'a file';
const folder = line(b.folder, 80);
const fileLine = `<p><b>File:</b> ${esc(file)}${folder ? ' <span style="color:#6B5E52">(' + esc(folder) + ')</span>' : ''}</p>`;
const portal = `<p><a href="${APP}">Open the portal</a></p>`;

if (kind === 'message' || kind === 'rejected') {
  const message = String(b.message ?? '').trim().slice(0, 4000);
  if (!message) return [];
  const rejected = kind === 'rejected';
  return [{ json: {
    subject: rejected ? `${who} rejected ${file}` : `${who} sent a message about ${file}`,
    html: intro(rejected ? 'rejected a file in the FTG portal. Their reason:' : 'sent a message in the FTG portal.')
      + fileLine
      + `<div style="margin:12px 0;padding:10px 14px;border-left:3px solid #E8B923;background:#FBF7EE;white-space:pre-wrap">${esc(message)}</div>`
      + '<p>To reply, open the file in <b>Documents</b> and press its chat icon.</p>'
      + portal,
  } }];
}

if (kind === 'approved') {
  return [{ json: {
    subject: `${who} approved ${file}`,
    html: intro('approved a file we sent them in the FTG portal.') + fileLine + portal,
  } }];
}

if (kind === 'questionnaire') {
  const month = line(b.month, 40);
  const answers = (Array.isArray(b.answers) ? b.answers : []).slice(0, 20).map(a => ({
    question: line(a?.question, 300),
    answer: line(a?.answer, 20) || 'Not answered',
    details: (Array.isArray(a?.details) ? a.details : []).slice(0, 20).map(d => String(d ?? '').trim().slice(0, 2000)).filter(Boolean),
  })).filter(a => a.question);
  const yes = answers.filter(a => a.answer === 'Yes').length;
  return [{ json: {
    subject: `${who} submitted their ${month || 'monthly'} questionnaire`,
    html: intro(`submitted their monthly questionnaire${month ? ` for <b>${esc(month)}</b>` : ''}`
        + (answers.length ? `, and answered Yes to ${yes} of ${answers.length}.` : '.'))
      + (answers.length ? '<ol>' + answers.map(a => `<li style="margin-bottom:8px"><b>${esc(a.answer)}</b>: ${esc(a.question)}`
          + (a.details.length ? `<div style="margin-top:4px;color:#6B5E52;white-space:pre-wrap">${a.details.map(esc).join('<br>')}</div>` : '')
          + '</li>').join('') + '</ol>' : '')
      + "<p>It is on the client's profile, under <b>Monthly questionnaire</b>.</p>"
      + portal,
  } }];
}

if (kind === 'account') {
  const change = line(b.change, 300);
  if (!change) return [];
  return [{ json: {
    subject: `${who} ${change}`,
    html: intro(`${esc(change)} in the FTG portal.`) + portal,
  } }];
}

return [];
